//! YAML-object normalization shared by editor fetch, validation, and apply operations.

use anyhow::{Context, Result};
use kube::api::DynamicObject;

const SERVER_MANAGED_METADATA_FIELDS: [&str; 4] = [
    "managedFields",
    "resourceVersion",
    "uid",
    "creationTimestamp",
];

pub(super) enum ReplacementPreparation {
    Ready(Box<DynamicObject>),
    Conflict {
        /// The version of the live object that the document conflicts with.
        current_resource_version: String,
    },
}

/// Remove fields which are generated by the API server and must not be sent back as part of an
/// editor payload. Clear both the dynamic JSON representation and kube's typed metadata because
/// serialization can read either one.
pub(super) fn strip_server_managed_metadata(object: &mut DynamicObject) {
    if let Some(metadata) = object.data.get_mut("metadata")
        && let Some(metadata) = metadata.as_object_mut()
    {
        for field in SERVER_MANAGED_METADATA_FIELDS {
            metadata.remove(field);
        }
    }
    object.metadata.managed_fields = None;
    object.metadata.resource_version = None;
    object.metadata.uid = None;
    object.metadata.creation_timestamp = None;
}

/// Convert an API response to the YAML shown by the editor while retaining the
/// version needed to safely replace that exact resource later.
pub(super) fn editor_yaml(object: &mut DynamicObject) -> Result<(String, String, String)> {
    let resource_version = resource_version(object)?;
    let resource_uid = resource_uid(object)?;
    strip_server_managed_metadata(object);
    Ok((
        serde_yaml::to_string(object)?,
        resource_version,
        resource_uid,
    ))
}

pub(super) fn resource_version(object: &DynamicObject) -> Result<String> {
    object
        .metadata
        .resource_version
        .clone()
        .context("Resource response did not include a resource version")
}

pub(super) fn resource_uid(object: &DynamicObject) -> Result<String> {
    object
        .metadata
        .uid
        .clone()
        .context("Resource response did not include a UID")
}

/// Normalize an edited object for a full replacement request. The editor does
/// not expose server-managed metadata, but replacement requires the version
/// that was fetched with the editor document.
pub(super) fn prepare_resource_replacement(object: &mut DynamicObject, resource_version: String) {
    strip_server_managed_metadata(object);
    object.metadata.resource_version = Some(resource_version);
}

/// Prepare editor content for a full replacement against the current object.
/// Status-only reconciliation may advance the resource version without
/// changing editable content; any other live change is a conflict. The current
/// status is always retained because controllers own it independently.
pub(super) fn prepare_editor_replacement(
    original_yaml: &str,
    edited_yaml: &str,
    expected_resource_version: &str,
    expected_resource_uid: &str,
    current: &mut DynamicObject,
) -> Result<ReplacementPreparation> {
    let current_resource_version = resource_version(current)?;
    if resource_uid(current)? != expected_resource_uid
        || (current_resource_version != expected_resource_version
            && has_non_status_changes(original_yaml, current)?)
    {
        return Ok(ReplacementPreparation::Conflict {
            current_resource_version,
        });
    }

    let mut edited: DynamicObject = serde_yaml::from_str(edited_yaml)?;
    retain_current_status(&mut edited, current);
    prepare_resource_replacement(&mut edited, current_resource_version);
    Ok(ReplacementPreparation::Ready(Box::new(edited)))
}

/// How many times the editor's document is prepared and sent while the live object keeps
/// changing in between. Controllers write status continuously, so a busy object can change
/// again after it was read.
const EDITOR_REPLACEMENT_ATTEMPTS: usize = 5;

/// The editor's document and the version and identity of the object it was fetched from.
pub(super) struct EditorDocument<'a> {
    pub(super) original_yaml: &'a str,
    pub(super) edited_yaml: &'a str,
    pub(super) resource_version: &'a str,
    pub(super) resource_uid: &'a str,
}

pub(super) enum EditorReplacement<T> {
    Sent(T),
    /// The live object changed beyond its status since the editor fetched it.
    Conflict {
        /// The version of the live object that the document conflicts with.
        current_resource_version: String,
    },
    Rejected(Box<kube::core::Status>),
}

/// Prepares the editor's document against the live object (see `prepare_editor_replacement`)
/// and sends it with `send`. A status update between reading the object and sending the
/// replacement still makes the API server reject the stale resource version, so the object is
/// read and checked again rather than the status update being reported as a conflict. `send`
/// must return a failed request's `kube::Error` without added context, so a 409 is recognised.
pub(super) async fn send_editor_replacement<T, Sent>(
    api: &kube::Api<DynamicObject>,
    resource_name: &str,
    document: &EditorDocument<'_>,
    mut send: impl FnMut(DynamicObject) -> Sent,
) -> Result<EditorReplacement<T>>
where
    Sent: Future<Output = Result<T>>,
{
    let mut attempt = 1;
    loop {
        let mut current = match api.get(resource_name).await {
            Ok(current) => current,
            // Once a replacement was rejected, report the object's new state (it may be gone)
            // like that rejection.
            Err(kube::Error::Api(status)) if attempt > 1 => {
                return Ok(EditorReplacement::Rejected(status));
            }
            Err(error) => return Err(error.into()),
        };
        let object = match prepare_editor_replacement(
            document.original_yaml,
            document.edited_yaml,
            document.resource_version,
            document.resource_uid,
            &mut current,
        )? {
            ReplacementPreparation::Ready(object) => *object,
            ReplacementPreparation::Conflict {
                current_resource_version,
            } => {
                return Ok(EditorReplacement::Conflict {
                    current_resource_version,
                });
            }
        };
        let error = match send(object).await {
            Ok(sent) => return Ok(EditorReplacement::Sent(sent)),
            Err(error) => error.downcast::<kube::Error>()?,
        };
        match error {
            kube::Error::Api(status)
                if status.code == 409 && attempt < EDITOR_REPLACEMENT_ATTEMPTS =>
            {
                attempt += 1;
            }
            kube::Error::Api(status) => return Ok(EditorReplacement::Rejected(status)),
            error => return Err(error.into()),
        }
    }
}

fn retain_current_status(edited: &mut DynamicObject, current: &DynamicObject) {
    let Some(edited_data) = edited.data.as_object_mut() else {
        return;
    };
    match current.data.get("status") {
        Some(status) => {
            edited_data.insert("status".into(), status.clone());
        }
        None => {
            edited_data.remove("status");
        }
    }
}

/// Return whether an object has changed in a way that a full replacement must
/// not overwrite. Resource status is reconciled independently by controllers,
/// so a status-only update is safe to retry with the current resource version.
pub(super) fn has_non_status_changes(
    original_yaml: &str,
    current: &mut DynamicObject,
) -> Result<bool> {
    let mut original: DynamicObject = serde_yaml::from_str(original_yaml)?;
    Ok(editable_value(&mut original)? != editable_value(current)?)
}

fn editable_value(object: &mut DynamicObject) -> Result<k8s_openapi::serde_json::Value> {
    strip_server_managed_metadata(object);
    let mut value = k8s_openapi::serde_json::to_value(object)?;
    if let Some(value) = value.as_object_mut() {
        value.remove("status");
    }
    Ok(value)
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::fake_kube_api::{FakeKubeApi, Reply, Request};

    #[test]
    fn strips_server_managed_fields_from_both_metadata_representations() {
        let mut object: DynamicObject =
            k8s_openapi::serde_json::from_value(k8s_openapi::serde_json::json!({
                "apiVersion": "v1",
                "kind": "ConfigMap",
                "metadata": {
                    "name": "settings",
                    "managedFields": [{}],
                    "resourceVersion": "4",
                    "uid": "uid-1",
                    "creationTimestamp": "2026-01-01T00:00:00Z"
                }
            }))
            .unwrap();
        // Dynamic objects received through kube retain this map, while direct serde
        // deserialization normalizes it into `ObjectMeta`. Exercise both paths.
        object.data.as_object_mut().unwrap().insert(
            "metadata".to_owned(),
            k8s_openapi::serde_json::json!({
                "name": "settings",
                "managedFields": [{}],
                "resourceVersion": "4",
                "uid": "uid-1",
                "creationTimestamp": "2026-01-01T00:00:00Z"
            }),
        );

        strip_server_managed_metadata(&mut object);

        let metadata = object.data["metadata"].as_object().unwrap();
        assert_eq!(metadata.get("name").unwrap(), "settings");
        for field in SERVER_MANAGED_METADATA_FIELDS {
            assert!(!metadata.contains_key(field));
        }
        assert!(object.metadata.managed_fields.is_none());
        assert!(object.metadata.resource_version.is_none());
        assert!(object.metadata.uid.is_none());
        assert!(object.metadata.creation_timestamp.is_none());
        let yaml = serde_yaml::to_string(&object).unwrap();
        assert!(yaml.contains("name: settings"));
        for field in SERVER_MANAGED_METADATA_FIELDS {
            assert!(!yaml.contains(field));
        }
    }

    #[test]
    fn editor_yaml_hides_the_resource_version_but_returns_it_for_replacement() {
        let mut object: DynamicObject =
            k8s_openapi::serde_json::from_value(k8s_openapi::serde_json::json!({
                "apiVersion": "v1",
                "kind": "ConfigMap",
                "metadata": {
                    "name": "settings",
                    "resourceVersion": "42",
                    "uid": "uid-1"
                }
            }))
            .unwrap();

        let (yaml, resource_version, resource_uid) = editor_yaml(&mut object).unwrap();

        assert_eq!(resource_version, "42");
        assert_eq!(resource_uid, "uid-1");
        assert!(!yaml.contains("resourceVersion"));
    }

    #[test]
    fn replacement_restores_only_the_resource_version() {
        let mut object: DynamicObject =
            k8s_openapi::serde_json::from_value(k8s_openapi::serde_json::json!({
                "apiVersion": "v1",
                "kind": "ConfigMap",
                "metadata": {
                    "name": "settings",
                    "uid": "uid-1",
                    "managedFields": [{}]
                }
            }))
            .unwrap();

        prepare_resource_replacement(&mut object, "42".into());

        let value = k8s_openapi::serde_json::to_value(object).unwrap();
        let metadata = value["metadata"].as_object().unwrap();
        assert_eq!(metadata.get("resourceVersion").unwrap(), "42");
        assert!(!metadata.contains_key("uid"));
        assert!(!metadata.contains_key("managedFields"));
    }

    #[test]
    fn status_only_changes_do_not_conflict_with_a_replacement() {
        let original_yaml = r#"
apiVersion: apps/v1
kind: Deployment
metadata:
  name: api
spec:
  replicas: 1
"#;
        let mut current: DynamicObject =
            k8s_openapi::serde_json::from_value(k8s_openapi::serde_json::json!({
                "apiVersion": "apps/v1",
                "kind": "Deployment",
                "metadata": {
                    "name": "api",
                    "resourceVersion": "2",
                    "uid": "uid-1"
                },
                "spec": {
                    "replicas": 1
                },
                "status": {
                    "availableReplicas": 1
                }
            }))
            .unwrap();

        assert!(!has_non_status_changes(original_yaml, &mut current).unwrap());
    }

    #[test]
    fn editable_changes_conflict_with_a_replacement() {
        let original_yaml = r#"
apiVersion: v1
kind: ConfigMap
metadata:
  name: settings
data:
  mode: production
"#;
        let mut current: DynamicObject =
            k8s_openapi::serde_json::from_value(k8s_openapi::serde_json::json!({
                "apiVersion": "v1",
                "kind": "ConfigMap",
                "metadata": {
                    "name": "settings",
                    "resourceVersion": "2",
                    "uid": "uid-1"
                },
                "data": {
                    "mode": "maintenance"
                }
            }))
            .unwrap();

        assert!(has_non_status_changes(original_yaml, &mut current).unwrap());
    }

    #[test]
    fn replacement_preparation_rebases_a_status_only_update() {
        let original_yaml = "apiVersion: v1\nkind: ConfigMap\nmetadata:\n  name: settings\ndata:\n  mode: production\n";
        let edited_yaml = "apiVersion: v1\nkind: ConfigMap\nmetadata:\n  name: settings\ndata:\n  mode: maintenance\n";
        let mut current: DynamicObject =
            k8s_openapi::serde_json::from_value(k8s_openapi::serde_json::json!({
                "apiVersion": "v1",
                "kind": "ConfigMap",
                "metadata": {
                    "name": "settings",
                    "resourceVersion": "2",
                    "uid": "uid-1"
                },
                "data": {
                    "mode": "production"
                },
                "status": {
                    "ignored": true
                }
            }))
            .unwrap();

        let ReplacementPreparation::Ready(prepared) =
            prepare_editor_replacement(original_yaml, edited_yaml, "1", "uid-1", &mut current)
                .unwrap()
        else {
            panic!("status-only updates should not conflict");
        };

        assert_eq!(prepared.metadata.resource_version.as_deref(), Some("2"));
        assert_eq!(prepared.data["data"]["mode"], "maintenance");
        assert_eq!(prepared.data["status"]["ignored"], true);
    }

    #[test]
    fn replacement_preparation_preserves_live_status_over_editor_status() {
        let yaml = "apiVersion: v1\nkind: ConfigMap\nmetadata:\n  name: settings\nstatus:\n  mode: stale\n";
        let mut current: DynamicObject =
            k8s_openapi::serde_json::from_value(k8s_openapi::serde_json::json!({
                "apiVersion": "v1",
                "kind": "ConfigMap",
                "metadata": {
                    "name": "settings",
                    "resourceVersion": "1",
                    "uid": "uid-1"
                },
                "status": {
                    "mode": "live"
                }
            }))
            .unwrap();

        let ReplacementPreparation::Ready(prepared) =
            prepare_editor_replacement(yaml, yaml, "1", "uid-1", &mut current).unwrap()
        else {
            panic!("an unchanged object should prepare for replacement");
        };

        assert_eq!(prepared.data["status"]["mode"], "live");
    }

    #[test]
    fn replacement_preparation_conflicts_when_the_resource_was_recreated() {
        let yaml = "apiVersion: v1\nkind: ConfigMap\nmetadata:\n  name: settings\n";
        let mut current: DynamicObject =
            k8s_openapi::serde_json::from_value(k8s_openapi::serde_json::json!({
                "apiVersion": "v1",
                "kind": "ConfigMap",
                "metadata": {
                    "name": "settings",
                    "resourceVersion": "2",
                    "uid": "new-uid"
                }
            }))
            .unwrap();

        let ReplacementPreparation::Conflict {
            current_resource_version,
        } = prepare_editor_replacement(yaml, yaml, "1", "old-uid", &mut current).unwrap()
        else {
            panic!("a recreated resource conflicts");
        };
        assert_eq!(current_resource_version, "2");
    }

    /// The live ConfigMap as a fake API server returns it: `data.mode` is editable, and
    /// `status.observed` stands in for a controller-owned status.
    fn live_settings(resource_version: &str, mode: &str, observed: u32) -> String {
        k8s_openapi::serde_json::json!({
            "apiVersion": "v1",
            "kind": "ConfigMap",
            "metadata": {
                "name": "settings",
                "namespace": "default",
                "resourceVersion": resource_version,
                "uid": "uid-1"
            },
            "data": { "mode": mode },
            "status": { "observed": observed }
        })
        .to_string()
    }

    fn conflict_status() -> String {
        k8s_openapi::serde_json::json!({
            "kind": "Status",
            "apiVersion": "v1",
            "status": "Failure",
            "message": "Operation cannot be fulfilled on configmaps \"settings\": the object has been modified",
            "reason": "Conflict",
            "code": 409
        })
        .to_string()
    }

    /// Sends the editor's `data.mode: maintenance` edit of the ConfigMap fetched at version 1
    /// to a fake API server that answers with `responses`.
    async fn replace_settings(
        responses: Vec<Reply>,
    ) -> (EditorReplacement<DynamicObject>, Vec<Request>) {
        // Responses the replacement does not ask for are left unserved.
        let server = FakeKubeApi::start_sequence(responses).await;
        let client = server.client();
        let api: kube::Api<DynamicObject> = kube::Api::namespaced_with(
            client,
            "default",
            &kube::api::ApiResource::erase::<k8s_openapi::api::core::v1::ConfigMap>(&()),
        );
        let original_yaml = "apiVersion: v1\nkind: ConfigMap\nmetadata:\n  name: settings\n  namespace: default\ndata:\n  mode: production\nstatus:\n  observed: 1\n";
        let edited_yaml = original_yaml.replace("mode: production", "mode: maintenance");
        let document = EditorDocument {
            original_yaml,
            edited_yaml: &edited_yaml,
            resource_version: "1",
            resource_uid: "uid-1",
        };

        let replacement = send_editor_replacement(&api, "settings", &document, |object| {
            let api = api.clone();
            async move {
                Ok(api
                    .replace("settings", &kube::api::PostParams::default(), &object)
                    .await?)
            }
        })
        .await
        .unwrap();
        (replacement, server.requests())
    }

    #[tokio::test]
    async fn a_status_update_that_races_the_replacement_is_rebased_and_sent_again() {
        let (replacement, requests) = replace_settings(vec![
            Reply::ok_json(live_settings("2", "production", 2)),
            Reply::json(409, conflict_status()),
            Reply::ok_json(live_settings("3", "production", 3)),
            Reply::ok_json(live_settings("4", "maintenance", 3)),
        ])
        .await;

        let EditorReplacement::Sent(replaced) = replacement else {
            panic!("a status-only race should not be reported as a conflict");
        };
        assert_eq!(replaced.metadata.resource_version.as_deref(), Some("4"));
        let methods = requests
            .iter()
            .map(|request| request.method.as_str())
            .collect::<Vec<_>>();
        assert_eq!(methods, ["GET", "PUT", "GET", "PUT"]);
        let resent: DynamicObject = k8s_openapi::serde_json::from_str(&requests[3].body).unwrap();
        assert_eq!(resent.metadata.resource_version.as_deref(), Some("3"));
        assert_eq!(resent.data["data"]["mode"], "maintenance");
        assert_eq!(resent.data["status"]["observed"], 3);
    }

    #[tokio::test]
    async fn an_editable_change_that_races_the_replacement_is_a_conflict() {
        let (replacement, requests) = replace_settings(vec![
            Reply::ok_json(live_settings("2", "production", 2)),
            Reply::json(409, conflict_status()),
            Reply::ok_json(live_settings("3", "standby", 2)),
        ])
        .await;

        let EditorReplacement::Conflict {
            current_resource_version,
        } = replacement
        else {
            panic!("a real change must conflict");
        };
        assert_eq!(
            current_resource_version, "3",
            "the version the change was found at"
        );
        assert_eq!(requests.len(), 3, "a real change must not be overwritten");
    }

    #[tokio::test]
    async fn an_invalid_replacement_is_rejected_without_a_retry() {
        let invalid = k8s_openapi::serde_json::json!({
            "kind": "Status",
            "apiVersion": "v1",
            "status": "Failure",
            "message": "ConfigMap \"settings\" is invalid",
            "reason": "Invalid",
            "code": 422
        })
        .to_string();
        let (replacement, requests) = replace_settings(vec![
            Reply::ok_json(live_settings("2", "production", 2)),
            Reply::json(422, invalid),
        ])
        .await;

        let EditorReplacement::Rejected(status) = replacement else {
            panic!("the validation error should be reported");
        };
        assert_eq!(status.code, 422);
        assert_eq!(requests.len(), 2);
    }

    #[tokio::test]
    async fn a_replacement_that_keeps_being_rejected_reports_the_rejection() {
        let mut responses = Vec::new();
        for version in 2..2 + EDITOR_REPLACEMENT_ATTEMPTS {
            responses.push(Reply::ok_json(live_settings(
                &version.to_string(),
                "production",
                2,
            )));
            responses.push(Reply::json(409, conflict_status()));
        }
        let (replacement, requests) = replace_settings(responses).await;

        let EditorReplacement::Rejected(status) = replacement else {
            panic!("the last rejection should be reported");
        };
        assert_eq!(status.code, 409);
        assert_eq!(requests.len(), 2 * EDITOR_REPLACEMENT_ATTEMPTS);
    }
}
